class TCPClient:
    """A non-blocking TCP connection factory with a configurable DNS resolver.

        .. versionchanged:: 5.0
           The ``io_loop`` argument (deprecated since version 4.1) has been removed.
        """
    def __init__(self, resolver: Optional[Resolver] = None) -> None:
