class OptionParser:
    """A collection of options, a dictionary with object-like access.

        Normally accessed via static functions in the `tornado.options` module,
        which reference a global instance.

        This class provides methods to define and manage command-line arguments and configuration settings. It allows users to set up various options that can be accessed later in the program.
    """
    def __init__(self) -> None:
        # we have to use self.__dict__ because we override setattr.
        self.__dict__["_options"] = {}
        self.__dict__["_parse_callbacks"] = []

    def define(
        self, 
        name: str, 
        type: type, 
        help: str, 
        callback=None
    ) -> None:
        """Define a new option with the given name, type, and help text. Optionally specify a callback function to be called when this option is parsed."""
        self._options[name] = {"type": type, "help": help, "callback": callback}

    def _help_callback(self, value: bool) -> None:
        if value:
            self.print_help()
            sys.exit(0)

