class RuleRouter:
    """Rule-based router implementation."""
    def __init__(self, rules: Optional[_RuleList] = None) -> None:
        """Constructs a router from an ordered list of rules::

            RuleRouter([
                Rule(PathMatches("/handler"), Target),
                # ... more rules
            ])

        You can also omit explicit `Rule` constructor and use tuples of arguments::

            RuleRouter([
                ("/handler", Target),
            ])

        `PathMatches` is a default matcher, so the example above can be simplified::

            RuleRouter([
                "/handler", Target),
            ])

        In the examples above, ``Target`` can be a nested `Router` instance, an instance of
        `~.httputil.HTTPServerConnectionDelegate` or an old-style callable,
        accepting a request argument.

        :arg rules: a list of `Rule` instances or tuples of `Rule`
            constructor arguments.
        """
        self.rules = []  # type: List[Rule]
        if rules:
            self.add_rules(rules)

    def add_rules(self, rules: List[_RuleList]) -> None:
        """Adds a list of rules to the router. Each rule can be either a tuple (path pattern, target) or an instance of `Rule`.

        :param rules: A list of rule tuples or instances of `Rule`.
        """
        for rule in rules:
            if isinstance(rule, Rule):
                self.rules.append(rule)
            elif isinstance(rule, tuple) and len(rule) == 2:
                path_pattern, target = rule
                self.rules.append(Rule(PathMatches(path_pattern), target))
            else:
                raise ValueError("Each rule must be either a Rule instance or a (path pattern, target) tuple.")

    def get_target_delegate(
        self, target: Any, request: httputil.HTTPServerRequest, **target_params: Any
    ) -> Optional[httputil.HTTPMessageDelegate]:
        """Returns an instance of `~.httputil.HTTPMessageDelegate` for a
        Rule's target. This method is called by `~.find_handler` and can be
        extended to provide additional target types.

        :arg target: a Rule's target.
        :arg httputil.HTTPServerRequest request: current request.
        :arg target_params: additional parameters that can be useful
            for `~.httputil.HTTPMessageDelegate` creation.
        """
        if isinstance(target, Router):
            return target.find_handler(request, **target_params)

        elif isinstance(target, httputil.HTTPServerConnectionDelegate):
            assert request.connection is not None
            return target.start_request(request.server_connection, request.connection)

        elif callable(target):
            assert request.connection is not None
            return _CallableAdapter(
                partial(target, **target_params), request.connection
            )

        return None
