class HostMatches:
    """
    Matches requests from hosts specified by ``host_pattern`` regex.

    Parameters:
        host_pattern (Union[str, Pattern]): The regex pattern to match against the request's host name. If a string is provided, it should end with a dollar sign ($) to indicate the end of the string.

    Methods:
        match(request: httputil.HTTPServerRequest) -> Optional[Dict[str, Any]]: Matches the given HTTP server request against the stored regex pattern and returns a dictionary if there is a match, otherwise returns None.

    Examples:
        To create an instance of HostMatches for matching requests from hosts that end with ".example.com":
            host_matches = HostMatches(".*\.example\.com$")

        To use the match method to check if a request's host name matches the pattern:
