class PathMatches:
    """Matches requests with paths specified by ``path_pattern`` regex."""

    def __init__(self, path_pattern: Union[str, Pattern]) -> None:
        """Initializes a new instance of the PathMatches class.

        This constructor takes a `path_pattern` which can be either a string or a compiled regular expression pattern. If provided as a string, it is automatically converted to a regex pattern ending with `$`. The regex pattern must have either all named groups or all positional groups; otherwise, an assertion error will be raised.

        Parameters:
            path_pattern (Union[str, Pattern]): A string representing the regex pattern for matching paths, or a compiled regular expression pattern.

        Raises:
            AssertionError: If the regex pattern does not have all named groups or all positional groups.

        Example:
            >>> pm = PathMatches("/([0-9]{4})/([a-z-]+)/")
            >>> print(pm.regex.pattern)  # Output will be "/([0-9]{4})/([a-z-]+)/$"

            >>> import re
            >>> compiled_pattern = re.compile("/([0-9]{4})/([a-z-]+)/")
            >>> pm = PathMatches(compiled_pattern)
            >>> print(pm.regex.pattern)  # Output will be the same as the string pattern, ending with "$"

        Note:
            The regex pattern must either have all named groups or all positional groups to avoid ambiguity in matching. If a string is provided and does not end with `$`, it will automatically append `$` to ensure it matches the entire path.
        """
        if isinstance(path_pattern, basestring_type):
            if not path_pattern.endswith("$"):
                path_pattern += "$"
            self.regex = re.compile(path_pattern)
        else:
            self.regex = path_pattern

        assert len(self.regex.groupindex) in (0, self.regex.groups), (
            "groups in url regexes must either be all named or all positional: %r" % self.regex.pattern
        )

        self._path, self._group_count = self._find_groups()

    def _find_groups(self) -> Tuple[Optional[str], Optional[int]]:
        """Returns a tuple (reverse string, group count) for a url.

        For example: Given the url pattern /([0-9]{4})/([a-z-]+)/, this method would return ('/%s/%s/', 2).

        This method is used internally to find the reverse string representation of the regex pattern and the count of capturing groups. It ensures that the regex pattern has either all named or all positional groups to avoid ambiguity in matching.

        Returns:
            Tuple[Optional[str], Optional[int]]: A tuple containing the original path pattern as a string (with optional trailing `$`) and the count of capturing groups in the regex pattern. If the regex pattern cannot be reversed, it returns `None`.
        """
        pattern = self.regex.pattern
        if pattern.startswith("^"):
            pattern = pattern[1:]
        if pattern.endswith("$"):
            pattern = pattern[:-1]

        if self.regex.groups != pattern.count("("):
            # The pattern is too complicated for our simplistic matching, so we can't support reversing it.
            return None, None

        pieces = []
        for fragment in pattern.split("("):
            if ")" in fragment:
                paren_loc = fragment.index(")")
                if paren_loc >= 0:
                    try:
                        unescaped_fragment = re_unescape(fragment[paren_loc + 1 :])
                    except ValueError:
                        # If we can't unescape part of it, we can't reverse this url.
                        return (None, None)
                    pieces.append("%s" + unescaped_fragment)
            else:
                try:
                    unescaped_fragment = re_unescape(fragment)
                except ValueError:
                    # If we can't unescape part of it, we can't reverse this url.
                    return (None, None)
                pieces.append(unescaped_fragment)

        return "".join(pieces), self.regex.groups
